#include <bits/stdc++.h>
using namespace std;

vector<int> parseStringToIntArray(const string& s) {
    vector<int> nums;
    stringstream ss(s);
    int num;
    while (ss >> num) {
        nums.push_back(num);
    }
    return nums;
}

class Cutting {
public:
    bool checkBalance(const vector<int>& array, int index) {
        int evenCount = 0, oddCount = 0;
        for (int i = 0; i <= index; i++) {
            if (array[i] % 2 == 0) evenCount++;
            else oddCount++;
        }
        return evenCount == oddCount;
    }

    int findCutIndex(const vector<int>& array, int coinsLeft, const unordered_set<int>& used) {
        int minIdx = -1;
        int minCost = coinsLeft + 1;
        for (int i = 1; i < (int)array.size() - 1; i++) {
            if (used.count(i)) continue;
            int cost = abs(array[i] - array[i + 1]);
            if (cost < minCost && checkBalance(array, i)) {
                minCost = cost;
                minIdx = i;
            }
        }
        return minIdx;
    }

    int maxNumberOfCuts(int n, int b, const vector<int>& a) {
        int coins = b;
        int cuts = 0;
        unordered_set<int> usedIndices;
        while (coins > 0) {
            int idx = findCutIndex(a, coins, usedIndices);
            if (idx >= 0) {
                usedIndices.insert(idx);
                int cost = abs(a[idx] - a[idx + 1]);
                coins -= cost;
                cuts++;
            } else {
                break;
            }
        }
        return cuts;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string line1, line2;
    getline(cin, line1);
    getline(cin, line2);
    vector<int> nB = parseStringToIntArray(line1);
    vector<int> a = parseStringToIntArray(line2);
    int n = nB[0];
    int b = nB[1];
    Cutting c;
    cout << c.maxNumberOfCuts(n, b, a) << "\n";
    return 0;
}

